def PIGGY(n=0):
    """The monthly saver: a coin drops into the piggy bank every period, and beside it the balance grows, deposits and interest."""
    if MODE == 'pdf':
        return ''
    coins = ''.join(f'<g class="pc c{i}"><circle r="15" fill="#ffd37a" stroke="#a86703" stroke-width="3"/><text y="6" font-size="17" text-anchor="middle" font-weight="800" fill="#a86703">₪</text></g>' for i in range(3))
    pig = ('<g class="pb"><ellipse cx="170" cy="190" rx="112" ry="80" fill="#ffb3c1"/><path d="M92 128l-10-34 38 16z" fill="#ff8fa6"/><circle cx="276" cy="186" r="30" fill="#ff8fa6"/><circle cx="267" cy="182" r="5" fill="#7a2a3a"/><circle cx="285" cy="182" r="5" fill="#7a2a3a"/>'
           '<circle cx="222" cy="160" r="8" fill="#16213a"/><circle cx="225" cy="157" r="2.6" fill="#fff"/><path d="M228 214q14 12 30 4" fill="none" stroke="#7a2a3a" stroke-width="4" stroke-linecap="round"/>'
           '<path d="M112 258v26M224 258v26" stroke="#ff8fa6" stroke-width="22" stroke-linecap="round"/><path d="M58 186q-22-4-18 14q4 14 16 6" fill="none" stroke="#ff8fa6" stroke-width="6" stroke-linecap="round"/>'
           '<rect x="140" y="106" width="60" height="11" rx="5" fill="#7a2a3a"/></g>')
    bars = ''
    for i in range(6):
        dep = 22 * (i + 1); intr = 2 + i * i * 1.6; x = 350 + i * 27
        bars += f'<g class="bar b{i}"><rect x="{x}" y="{270 - dep:.0f}" width="20" height="{dep:.0f}" rx="3" fill="#ffd37a" stroke="#a86703" stroke-width="1.5"/><rect x="{x}" y="{270 - dep - intr:.0f}" width="20" height="{intr:.0f}" rx="3" fill="#0f9d90"/></g>'
        bars += f'<text x="{x + 10}" y="288" font-size="13" text-anchor="middle" font-weight="700" fill="#5d6a86">{i + 1}</text>'
    g = (coins + pig + '<line x1="340" y1="271" x2="516" y2="271" stroke="#1b2d55" stroke-width="2.5"/>' + bars
         + '<rect x="352" y="34" width="14" height="14" rx="3" fill="#ffd37a" stroke="#a86703" stroke-width="1.5"/><text x="372" y="46" font-size="15" font-weight="700" fill="#1b2d55" direction="rtl" text-anchor="end">ההפקדות</text>'
         + '<rect x="352" y="56" width="14" height="14" rx="3" fill="#0f9d90"/><text x="372" y="68" font-size="15" font-weight="700" fill="#0f9d90" direction="rtl" text-anchor="end">הריבית שנצברה</text>'
         + '<text x="430" y="300" font-size="13" text-anchor="middle" font-weight="700" fill="#5d6a86" direction="rtl">חודש</text>')
    inner = _svg(g, '0 -10 530 314', 'pig') + '<div class="anim-cap">' + TX('בכל חודש נכנסת עוד הפקדה, וכל מה שכבר בפנים ממשיך לצבור ריבית.') + '</div>'
    return ST(n, inner, cls='card animw big') if n else f'<div class="card animw big">{inner}</div>'


